const C='crate::translation_core::f64_inclusive_contains',vectorRoot=process.env.ROUTER_CORE_RANGE_VECTOR_DIR;
let vectors=[];
const retain=(kind,value)=>{vectors.push({kind,value});return value;};
const hash=value=>createHash('sha256').update(value).digest('hex');
const encoded=value=>typeof value==='number'?(Number.isNaN(value)?'NaN':value===Infinity?'+Infinity':value===-Infinity?'-Infinity':Object.is(value,-0)?'-0':value):value;
const test=(name,run)=>testCase(name,{timeout:60_000},async()=>{vectors=[];try{await run();}finally{if(vectorRoot){mkdirSync(vectorRoot,{recursive:true});writeFileSync(join(vectorRoot,Buffer.from(name).toString('hex')+'.json'),JSON.stringify({name,vectors},(_,value)=>typeof value==='bigint'?{$integer:String(value)}:encoded(value))+'\n');}}});
function files(source,{facade=ROUTER_FORMATTING_FACADE_SOURCE,leaf=ROUTER_CORE_RANGES_SOURCE,root='pub mod translation_core;\n',extra={}}={}){
  return {'src/lib.rs':root+source,'src/translation_core.rs':facade,'src/translation_core/primitives.rs':ROUTER_CORE_PRIMITIVES_SOURCE,'src/translation_core/ranges.rs':leaf,...extra};
}
function project(source,options){const input=files(source,options);retain('complete-input',input);return retain('complete-result',translateProject({entry:'src/lib.rs',paths:Object.keys(input),readSource:path=>input[path]}));}
const has=(result,name)=>result.meta.executable.some(item=>item.name===name);
function checked(result){const canonical=JSON.stringify(result.meta.checkedSemanticProgram),program=parseProgram(canonical);retain('complete-checked-meta',canonical);assert.equal(serializeProgram(program),canonical);return program;}
async function targets(result,run){retain('complete-targets',{javascript:result.javascript,typescript:result.typescript});await verifyTypedTargets(result,run,{childTimeoutMs:20_000});}
// Authored expected booleans; no use of the implementation's comparison code.
const cases=[
  [0,1,0,true],[0,1,1,true],[0,1,0.5,true],[0,1,-Number.MIN_VALUE,false],[0,1,1.0000000000000002,false],
  [-2,2,-2,true],[-2,2,2,true],[-2,2,-3,false],[-2,2,3,false],[2,-2,0,false],
  [-0,0,-0,true],[0,-0,0,true],[-0,-0,-0,true],
  [-Infinity,Infinity,0,true],[-Infinity,Infinity,Infinity,true],[-Infinity,Infinity,-Infinity,true],
  [Infinity,Infinity,Infinity,true],[-Infinity,-Infinity,-Infinity,true],[Infinity,-Infinity,0,false],
  [NaN,1,0,false],[0,NaN,0,false],[0,1,NaN,false],[-Infinity,Infinity,NaN,false],
  [-Number.MAX_VALUE,Number.MAX_VALUE,Number.MAX_VALUE,true],[-Number.MIN_VALUE,Number.MIN_VALUE,0,true],
];

test('owned range facade leaf and checked primitive operation retain complete source and semantic boundaries',async()=>{
  const physical=readFileSync(new URL('../../../src/translation_core/ranges.rs',import.meta.url),'utf8');
  retain('complete-owned-leaf',{physical,registered:ROUTER_CORE_RANGES_SOURCE,sha256:ROUTER_CORE_RANGES_SHA256,contract:ROUTER_CORE_RANGE_CONTRACT});
  assert.equal(physical,ROUTER_CORE_RANGES_SOURCE);assert.equal(hash(physical),ROUTER_CORE_RANGES_SHA256);
  const stage=transportConcreteSyntaxSource(physical,{language:'Rust'});assert.equal(transportConcreteSyntaxMeta(stage.meta).source,physical);
  assert.equal(Object.isFrozen(ROUTER_CORE_RANGE_CONTRACT.params),true);
  const result=project(`pub fn check(lower:f64,upper:f64,value:f64)->bool{${C}(lower,upper,value)}`);
  assert.equal(has(result,'check'),true);checked(result);
  retain('independent-full-IEEE-vectors',cases);
  await targets(result,api=>{const actual=cases.map(([lower,upper,value])=>api.check(lower,upper,value));retain('actual-target-results',actual);assert.deepEqual(actual,cases.map(row=>row[3]));});
  assert.equal(result.meta.runtimeParity,false);
});

test('runtime IEEE outcomes do not coerce caller objects and evaluate arguments left to right once',()=>{
  const actual=cases.map(([lower,upper,value])=>contains(lower,upper,value));retain('actual-runtime-IEEE-results',actual);assert.deepEqual(actual,cases.map(row=>row[3]));
  let hooks=0;const hostile={valueOf(){hooks++;throw Error('coercion');},[Symbol.toPrimitive](){hooks++;throw Error('coercion');}};
  const invalid=[undefined,null,'1',1n,{},new Number(1),hostile],outcomes=[];
  for(const value of invalid)for(let position=0;position<3;position++){const args=[0,1,0.5];args[position]=value;let error;try{contains(...args);}catch(caught){error={name:caught.name,message:caught.message};}outcomes.push({position,error});assert.equal(error?.name,'TypeError');}
  retain('all-invalid-runtime-outcomes',outcomes);assert.equal(hooks,0);
  const tape=[],read=(name,value)=>{tape.push(name);return value;};
  const answer=contains(read('lower',0),read('upper',1),read('value',0.5));retain('actual-argument-order',{tape,answer});assert.deepEqual(tape,['lower','upper','value']);assert.equal(answer,true);
  tape.length=0;assert.throws(()=>contains(read('lower',hostile),read('upper',1),read('value',0)),TypeError);assert.deepEqual(tape,['lower','upper','value']);assert.equal(hooks,0);
});

test('nested owned calls and checked function arguments preserve ordinary call lowering in both targets',async()=>{
  const source=`fn lower()->f64{-2.0} fn upper()->f64{2.0} fn identity(v:f64)->f64{v} pub fn answer(v:f64)->bool{${C}(lower(),upper(),identity(v))} pub fn combined(v:f64)->bool{${C}(-2.0,2.0,v)&&${C}(0.0,1.0,v)}`;
  const separate=`// Physical module offset Ω😀\n pub fn physical(v:f64)->bool{${C}(-2.0,2.0,v)}`,inline=`pub mod nested { // Inline module offset Ω😀\n pub fn inline(v:f64)->bool{${C}(0.0,1.0,v)} }`;
  const result=project(source+' pub mod child; '+inline,{extra:{'src/child.rs':separate}});for(const name of ['lower','upper','identity','answer','combined','child.physical','nested.inline'])assert.equal(has(result,name),true,name);checked(result);
  await targets(result,api=>{const values=[-3,-2,-0,0,0.5,1,2,3,NaN,Infinity],observed=values.map(value=>[api.answer(value),api.combined(value)]);retain('all-nested-target-results',observed);assert.deepEqual(observed,[[false,false],[true,false],[true,true],[true,true],[true,true],[true,true],[true,false],[false,false],[false,false],[false,false]]);const relocated=values.map(value=>[api['child.physical'](value),api['nested.inline'](value)]);retain('physical-and-inline-module-target-results',relocated);assert.deepEqual(relocated,[[false,false],[true,false],[true,true],[true,true],[true,true],[true,true],[true,false],[false,false],[false,false],[false,false]]);});
});

test('changed facade routes leaf implementation and non-f64 ownership remain genuine refusals',()=>{
  const good=`pub fn bad(value:f64)->bool{${C}(0.0,1.0,value)}`;
  for(const options of [
    {facade:ROUTER_FORMATTING_FACADE_SOURCE.replace('mod ranges;','#[cfg(any())] mod ranges;')},
    {leaf:ROUTER_CORE_RANGES_SOURCE.replace('lower <= value && value <= upper','true')},
    {root:'mod translation_core;\n'},
    {root:'pub mod translation_core; use crate::translation_core as other;\n'},
    {extra:{'src/translation_core/ranges.rs':'pub fn f64_inclusive_contains(_:f64,_:f64,_:f64)->bool{true}'}},
  ]){const result=project(good,options);assert.equal(has(result,'bad'),false);}
  for(const source of [
    `pub fn bad(value:&f64)->bool{${C}(0.0,1.0,value)}`,
    `pub fn bad(value:f32)->bool{${C}(0.0,1.0,value)}`,
    `pub fn bad(value:u8)->bool{${C}(0.0,1.0,value)}`,
    `pub fn bad()->bool{${C}(0.0,1.0)}`,
    `pub fn bad()->bool{${C}(0.0,1.0,0.5,0.75)}`,
    `pub const fn bad(v:f64)->bool{${C}(0.0,1.0,v)}`,
    'pub fn bad(v:f64)->bool{crate::translation_core::unregistered(0.0,1.0,v)}',
  ])assert.equal(has(project(source),'bad'),false,source);
  assert.throws(()=>checkRouterCoreRangeCall({}, {k:'routerCoreF64InclusiveCall',args:[],span:{start:0,end:1}},new Map(),[],null),error=>error.kind==='type');

  // Construct two independently parsed, genuinely linked declarations. The
  // relocation is the existing source-link recipe, never an owner flag.
  const source=`pub fn answer()->bool{${C}(0.0,1.0,0.5)}`,input=files(source),full=input['src/lib.rs'];
  const graph=resolveModuleGraph({entry:'src/lib.rs',paths:Object.keys(input),readSource:path=>input[path]}),context=createMatchesMacroContext({modules:graph.modules});
  const item=sourceItems(full).find(item=>item.term==='fn'&&item.name==='answer');
  const relocate=(value,offset)=>Array.isArray(value)?value.map(row=>relocate(row,offset)):value&&typeof value==='object'?Object.fromEntries(Object.entries(value).map(([key,row])=>[key,key==='span'&&row?{start:row.start+offset,end:row.end+offset}:relocate(row,offset)])):value;
  const callOf=value=>{if(!value||typeof value!=='object')return null;if(value.k==='routerCoreF64InclusiveCall')return value;for(const child of Object.values(value)){if(Array.isArray(child)){for(const row of child){const found=callOf(row);if(found)return found;}}else {const found=callOf(child);if(found)return found;}}return null;};
  const original=()=>{
    const parser=new HostRustParser(tokenizeRust(full.slice(item.start,item.end)));configureMatchesMacroParser(parser,context,{file:'src/lib.rs',offset:item.start});parser.attributes();parser.visibility();
    const raw=parser.fn([]),semantic=relocate(raw,item.start+71);
    assert.equal(linkProjectDeclaration(parser,raw,semantic,{source:full,sourcePath:'src/lib.rs',itemSpan:{start:item.start,end:item.end},itemOffset:item.start,globalOffset:71,path:[],scope:null}),true);
    return {parser,raw,semantic,node:callOf(semantic),rawNode:callOf(raw)};
  };
  const left=original(),right=original(),checker=new HostChecker('Rust',[]),surface={language:'Rust',items:[left.semantic],main:null};
  const origin=originalParsedSyntaxNode(left.semantic,left.node);assert.strictEqual(origin.parser,left.parser);assert.strictEqual(origin.original,left.rawNode);assert.strictEqual(origin.actual,left.node);assert.deepEqual(origin.relocated,left.node);
  retain('complete-genuine-checker-program',checker.program(surface));
  const observed=retain('actual-linked-relocation-positive',{source:full,raw:left.raw,relocated:left.semantic,checked:checkRouterCoreRangeCall(checker,left.node,new Map(),[],{kind:'bool'})});
  assert.equal(observed.checked.k,'routerHostCall');
  const clone=structuredClone(left.node),copiedParent=structuredClone(left.semantic);
  assert.equal(originalParsedSyntaxNode(copiedParent,callOf(copiedParent)),null);
  assert.throws(()=>checkRouterCoreRangeCall(checker,clone,new Map(),[],{kind:'bool'}),error=>error.kind==='type');
  assert.throws(()=>checkRouterCoreRangeCall(checker,right.node,new Map(),[],{kind:'bool'}),error=>error.kind==='type');
  assert.throws(()=>captureRouterCoreRangeCalls({},surface),/original|checker|identity|prototype/i);
  let overrideCalls=0;checker.expr=()=>{overrideCalls++;throw Error('unexpected checker override');};
  assert.throws(()=>checkRouterCoreRangeCall(checker,left.node,new Map(),[],{kind:'bool'}),/original|method|callback|changed/i);delete checker.expr;assert.equal(overrideCalls,0);
  // Equal source/digest is insufficient: a node swapped after linking was
  // never present at that parent's approved relocation boundary.
  const crossChecker=new HostChecker('Rust',[]);
  retain('complete-independent-checker-program',crossChecker.program({language:'Rust',items:[right.semantic],main:null}));
  const oldBody=right.semantic.body;right.semantic.body=left.semantic.body;
  captureRouterCoreRangeCalls(crossChecker,{language:'Rust',items:[right.semantic],main:null});
  assert.equal(originalParsedSyntaxNode(right.semantic,left.node),null);
  assert.throws(()=>checkRouterCoreRangeCall(crossChecker,left.node,new Map(),[],{kind:'bool'}),error=>error.kind==='type');
  right.semantic.body=oldBody;captureRouterCoreRangeCalls(crossChecker,{language:'Rust',items:[right.semantic],main:null});
  assert.equal(checkRouterCoreRangeCall(crossChecker,right.node,new Map(),[],{kind:'bool'}).k,'routerHostCall');
  const before=left.node.args[0];left.node.args[0]=structuredClone(right.node.args[1]);
  assert.throws(()=>checkRouterCoreRangeCall(checker,left.node,new Map(),[],{kind:'bool'}),error=>error.kind==='type');left.node.args[0]=before;
  retain('source-association-refusal-controls',{clone,copiedParent,crossAnalysis:right.semantic,restored:checkRouterCoreRangeCall(checker,left.node,new Map(),[],{kind:'bool'})});

});

test('literal-range CST adoption keeps complete inverse maps and independently checked output',async()=>{
  const source='// Ω😀 untouched\r\npub fn bounded(value:f64)->bool{(0.0..=1.0).contains(&value)}\r\npub fn signed(value:f64)->bool{!(-2.0..=2.0).contains(&value)}\npub fn double(value:f64)->bool{!!(0.0..=1.0).contains(&value)}\npub fn conditional(value:f64)->bool{if !(0.0..=1.0).contains(&value){false}else{true}}\npub fn returning(value:f64)->bool{return !(0.0..=1.0).contains(&value);}\n';
  const proposal=retain('complete-CST-adoption',migrateCoreRanges(source));
  assert.equal(proposal.edits.length,5);assert.deepEqual(proposal.selections.map(row=>row.function),['bounded','signed','double','conditional','returning']);assert.equal(proposal.before.source,source);assert.equal(transportConcreteSyntaxMeta(proposal.before.meta).source,source);assert.equal(transportConcreteSyntaxMeta(proposal.after.meta).source,proposal.after.source);
  assert.deepEqual(proposal.trace.map(row=>row.phase),['language','repository']);assert.equal(proposal.executableAdmission,false);
  let inverse=proposal.after.source;for(const row of [...proposal.mapping].reverse())if(row.kind==='substitution')inverse=inverse.slice(0,row.after[0])+row.expected+inverse.slice(row.after[1]);assert.equal(inverse,source);
  assert.equal(migrateCoreRanges(proposal.after.source).edits.length,0);
  const result=project(proposal.after.source);assert.equal(has(result,'bounded'),true);assert.equal(has(result,'signed'),true);checked(result);
  await targets(result,api=>{const observed=[api.bounded(0),api.bounded(1),api.bounded(2),api.bounded(NaN),api.signed(-3),api.signed(-2),api.signed(2),api.signed(3),api.double(0.5),api.double(2),api.conditional(0.5),api.conditional(2),api.returning(0.5),api.returning(2)];retain('migrated-target-values',observed);assert.deepEqual(observed,[true,true,false,false,true,false,false,true,true,false,true,false,false,true]);});
  for(const prefix of ['!','!!','return !','return!','if !','if!']){const complete=`pub fn compact(value:f64)->bool{${prefix}(0.0..=1.0).contains(&value)}`,adopted=retain('complete-keyword-negation-proposal',migrateCoreRanges(complete));assert.equal(adopted.edits.length,1,prefix);assert.equal(adopted.after.source,complete.replace('(0.0..=1.0).contains(&value)',`${C}(0.0, 1.0, value)`));assert.equal(migrateCoreRanges(adopted.after.source).edits.length,0);}
});

test('ambiguous and nonliteral range syntax is preserved rather than granted an owner or borrow',()=>{
  const basic='pub fn value(v:f64)->bool{(0.0..=1.0).contains(&v)}';
  const sources=[
    'use unknown::*;'+basic,
    'trait Other{fn contains(self,v:&f64)->bool;}'+basic,
    '#[custom_attribute] '+basic,
    'pub fn value(v:f64)->bool{trait Local{fn other();}(0.0..=1.0).contains(&v)}',
    'pub fn value(v:f64)->bool{(0..=1).contains(&v)}',
    'pub fn value(v:f64)->bool{(0.0f32..=1.0f32).contains(&v)}',
    'pub fn value(v:f64)->bool{(0.0..1.0).contains(&v)}',
    'pub fn value(v:f64)->bool{(lower()..=1.0).contains(&v)}',
    'pub fn value(v:&f64)->bool{(0.0..=1.0).contains(v)}',
    'pub fn value(v:f64)->bool{(0.0..=1.0).contains(&(v+1.0))}',
    'pub fn value(v:f64)->bool{unknown!((0.0..=1.0).contains(&v))}',
    'pub fn value(v:f64)->bool{unknown ! ((0.0..=1.0).contains(&v))}',
    'pub fn value(v:f64)->bool{outer!{inner![(0.0..=1.0).contains(&v)]}}',
    'pub fn value(v:f64)->bool{r#if!((0.0..=1.0).contains(&v))}',
    'pub fn value(v:f64)->bool{r#return ! ((0.0..=1.0).contains(&v))}',
    'const TEXT:&str="(0.0..=1.0).contains(&v)"; // (0.0..=1.0).contains(&v)\n',
  ];
  for(const source of sources){const proposal=retain('complete-unchanged-refusal-proposal',migrateCoreRanges(source));assert.equal(proposal.after.source,source);assert.equal(proposal.edits.length,0);}
  assert.throws(()=>migrateCoreRanges({toString(){throw Error('must not coerce');}}),TypeError);
});

